package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import org.json.*;
/** Reuses the proven private test-profile backup; verifies actual Settings keys in a fresh process. */
public class SettingsPersistenceChecks extends AppearancePersistenceChecks {
 @Override File backupFile(){return new File(getTargetContext().getFilesDir(),"settings-test-backup.json");}
 View find(View v,String desc){if(desc.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View match=find(g.getChildAt(i),desc);if(match!=null)return match;}}return null;}
 @Override public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);JSONObject record;
  if("write".equals(stage)){backup=snapshot();record=new JSONObject().put("prefs",backup).put("pid",android.os.Process.myPid());try(OutputStream out=new FileOutputStream(backupFile())){out.write(record.toString().getBytes("UTF-8"));}}
  else{StringBuilder raw=new StringBuilder();try(BufferedReader in=new BufferedReader(new InputStreamReader(new FileInputStream(backupFile()),"UTF-8"))){String line;while((line=in.readLine())!=null)raw.append(line);}record=new JSONObject(raw.toString());backup=record.getJSONObject("prefs");check(record.getInt("pid")!=android.os.Process.myPid(),"Settings reload uses a different process");}
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long until=SystemClock.elapsedRealtime()+30000;while(!a.loaded&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.loaded,"app discovery ready");ui(()->new DashSettings(a).open("Home & Dock"));
  if("write".equals(stage)){ui(()->{((Switch)find(a.stage,"Setting calendar")).setChecked(false);((Switch)find(a.stage,"Setting 24h")).setChecked(false);find(a.stage,"Settings: Dock size").performClick();a.settingsScreen.dialog.getListView().performItemClick(null,1,1);});ui(()->{LauncherActivity.App selected=null;for(LauncherActivity.App app:a.apps)if(a.settingsScreen.actions.installed(app.component)){selected=app;break;}check(selected!=null&&a.settingsScreen.actions.select(2,selected),"favorite saved through validated Settings action");a.setJakimZone("SGR03");new DashSettings(a).open("Prayer Times");});ui(()->((Switch)find(a.stage,"Setting prayer_countdown")).setChecked(false));ui(()->new DashSettings(a).open("Panel"));ui(()->{find(a.stage,"Settings: Default panel mode").performClick();a.settingsScreen.dialog.getListView().performItemClick(null,2,2);});check(prefs.getInt("dock_size",0)==1&&!prefs.getBoolean("calendar",true),"Settings values saved");Thread.sleep(700);keep=true;}
  else{check(!prefs.getBoolean("calendar",true)&&!prefs.getBoolean("24h",true)&&!prefs.getBoolean("prayer_countdown",true),"widget/clock/countdown survive force-stop");check(prefs.getInt("dock_size",0)==1&&prefs.getInt("panel_mode",0)==2&&"SGR03".equals(prefs.getString("jakim_zone","")),"dock/Panel/zone survive force-stop");check(!((Switch)find(a.stage,"Setting calendar")).isChecked(),"reopened Settings displays persisted widget state");check(a.settingsScreen.actions.installed(prefs.getString("favorite_YouTube","")),"saved favorite is still installed");check(a.nativePanel==null&&a.fmPanel==null&&a.carPanel==null,"reopening Settings never auto-starts panels");}
  result.putString("stream","PASS: "+count+" complete Settings process-persistence "+stage+" checks\n");code=Activity.RESULT_OK;
 }catch(Throwable error){result.putString("stream","FAIL after "+count+": "+error+"\n");}finally{try{if(!keep)restore();}catch(Exception e){code=Activity.RESULT_CANCELED;result.putString("stream","FAIL restoring Settings test profile: "+e);}if(a!=null)ui(()->{if(a.appearanceEditor!=null)a.appearanceEditor.close();a.finish();});}finish(code,result);}
}
